import{describe,it,expect}from"vitest";import{editorialNote,demographicStats,radcliffeRegions,partitionTimeline,mountbattenPlanDetails,politicalLeaders,migrationCorridors,refugeeCampsData,archivalGallery,oralHistories,partitionQuiz,getTimelineEventById,filterTimelineEvents,filterLeaders,filterOralHistories,getCorridorById,evaluateQuiz,verifyNeutralityAndNonGraphicContent}from"../../frontend/partition-1947/partition-1947.js";const REQUIRED_TIMELINE_FIELDS=["id","date","title","phase","description","historicalSignificance"];describe("Editorial Framing & Neutrality Verification",()=>{it("contains an official editorial note emphasizing factual & respectful framing",()=>{expect(editorialNote).toBeDefined(),expect(editorialNote.title).toContain("Editorial Note"),expect(editorialNote.content).toContain("factual"),expect(editorialNote.content).toContain("respectful")}),it("scans all timeline content for absence of restricted graphic/sensational terms",()=>{const e=verifyNeutralityAndNonGraphicContent(partitionTimeline);expect(e.isNeutral).toBe(!0),expect(e.violations).toEqual([])})}),describe("Sourced Demographic & Migration Statistics",()=>{it("contains verified population displacement figures",()=>{expect(demographicStats.totalDisplaced).toContain("14"),expect(demographicStats.totalDisplacedNumeric).toBeGreaterThan(1e7),expect(demographicStats.migratedToIndia).toContain("7.2"),expect(demographicStats.migratedToPakistan).toContain("7.2")}),it("provides official historical sources and census citations",()=>{expect(Array.isArray(demographicStats.sources)).toBe(!0),expect(demographicStats.sources.length).toBeGreaterThanOrEqual(3);const e=demographicStats.sources.join(" ").toLowerCase();expect(e).toContain("census of india 1951"),expect(e).toContain("unhcr")})}),describe("Radcliffe Boundary Commission Regions",()=>{it("covers Punjab and Bengal boundary commissions with economic impacts",()=>{expect(radcliffeRegions.length).toBe(2);const e=radcliffeRegions.map(e=>e.name.toLowerCase());expect(e.some(e=>e.includes("punjab"))).toBe(!0),expect(e.some(e=>e.includes("bengal"))).toBe(!0),radcliffeRegions.forEach(e=>{expect(e.economicImpact).toBeDefined(),expect(e.economicImpact.length).toBeGreaterThan(10)})})}),describe("Mountbatten Plan Structure",()=>{it("defines the 3rd June 1947 Plan with 4 key provisions",()=>{expect(mountbattenPlanDetails).toBeDefined(),expect(mountbattenPlanDetails.announcementDate).toBe("June 3, 1947"),expect(mountbattenPlanDetails.keyProvisions.length).toBe(4)})}),describe("Timeline Events Dataset Integrity (1905–1950)",()=>{it("contains 14 chronological events spanning from 1905 to 1950",()=>{expect(partitionTimeline.length).toBe(14),expect(partitionTimeline[0].date).toContain("1905"),expect(partitionTimeline[partitionTimeline.length-1].date).toContain("1950")}),it("every timeline event contains required properties with valid text",()=>{partitionTimeline.forEach((e,t)=>{REQUIRED_TIMELINE_FIELDS.forEach(i=>{expect(e,`Timeline event at index ${t} missing field ${i}`).toHaveProperty(i),expect(typeof e[i]).toBe("string"),expect(e[i].trim().length).toBeGreaterThan(0)})})}),it("all timeline event IDs are unique",()=>{const e=partitionTimeline.map(e=>e.id);expect(new Set(e).size).toBe(e.length)})}),describe("Timeline Query Helpers",()=>{it("retrieves timeline event by ID or date",()=>{const e=getTimelineEventById("t-1947-06");expect(e).toBeDefined(),expect(e.title).toContain("Mountbatten Plan");const t=getTimelineEventById("August 14–15, 1947");expect(t).toBeDefined(),expect(t.title).toContain("Independence")}),it("filters timeline events by search query (e.g. Radcliffe or Resettlement or Swadeshi)",()=>{const e=filterTimelineEvents("Radcliffe");expect(e.length).toBeGreaterThan(0);const t=filterTimelineEvents("Swadeshi");expect(t.length).toBeGreaterThan(0);const i=filterTimelineEvents("Nehru-Liaquat");expect(i.length).toBeGreaterThan(0)}),it("returns empty array when search query matches nothing",()=>{const e=filterTimelineEvents("NonExistentPartitionEventXYZ");expect(e).toEqual([])})}),describe("Political Leaders Dataset & Filtering",()=>{it("contains major political figures across Indian, British, League, and Regional categories",()=>{expect(politicalLeaders.length).toBeGreaterThanOrEqual(8);const e=politicalLeaders.map(e=>e.name);expect(e).toContain("Lord Louis Mountbatten"),expect(e).toContain("Jawaharlal Nehru"),expect(e).toContain("Sardar Vallabhbhai Patel"),expect(e).toContain("Mahatma Gandhi"),expect(e).toContain("Muhammad Ali Jinnah"),expect(e).toContain("Sir Cyril Radcliffe")}),it("filters leaders correctly by category or search query",()=>{const e=filterLeaders("British Official");expect(e.length).toBeGreaterThan(0),expect(e.every(e=>"British Official"===e.category)).toBe(!0);const t=filterLeaders("Vallabhbhai");expect(t.length).toBe(1),expect(t[0].name).toContain("Patel")})}),describe("Migration Corridors & Refugee Crisis",()=>{it("defines 3 primary migration corridors (Punjab, Bengal, Sindh)",()=>{expect(migrationCorridors.length).toBe(3);const e=getCorridorById("corridor-punjab");expect(e).toBeDefined(),expect(e.name).toContain("Western Corridor")}),it("includes records of major relief camps like Kurukshetra and Ranaghat",()=>{expect(refugeeCampsData.length).toBeGreaterThanOrEqual(4);const e=refugeeCampsData.find(e=>"camp-kurukshetra"===e.id);expect(e).toBeDefined(),expect(e.capacity||e.peakCapacity).toContain("300,000")})}),describe("Archival Gallery & Oral Histories",()=>{it("contains archival media cards with valid historical citations",()=>{expect(archivalGallery.length).toBeGreaterThanOrEqual(4),archivalGallery.forEach(e=>{expect(e.title).toBeDefined(),expect(e.credit).toBeDefined()})}),it("contains oral history survivor testimonies and filter function",()=>{expect(oralHistories.length).toBeGreaterThanOrEqual(4);const e=filterOralHistories("Resilience");expect(e.length).toBeGreaterThan(0)})}),describe("Knowledge Quiz Evaluation Engine",()=>{it("has 10 educational questions with explanations",()=>{expect(partitionQuiz.length).toBe(10),partitionQuiz.forEach(e=>{expect(e.options.length).toBe(4),expect(e.explanation.length).toBeGreaterThan(5)})}),it("evaluates perfect score and returns Master badge",()=>{const e={};partitionQuiz.forEach(t=>{e[t.id]=t.correctIndex});const t=evaluateQuiz(e);expect(t.score).toBe(10),expect(t.percentage).toBe(100),expect(t.badge).toBe("Master Historical Archivist")}),it("handles partial or empty quiz answers gracefully",()=>{const e=evaluateQuiz({});expect(e.score).toBe(0),expect(e.percentage).toBe(0),expect(e.badge).toBe("Historical Explorer")})});